// Builds a USGS catalog query from the inject payload {start, end, minmag}.
// USGS returns at most 20000 events per request - keep the range small enough (e.g. 1 year at M5+).
const { start, end, minmag } = msg.payload;
msg.url = 'https://earthquake.usgs.gov/fdsnws/event/1/query?format=geojson&eventtype=earthquake' +
  `&orderby=time-asc&starttime=${encodeURIComponent(start)}&endtime=${encodeURIComponent(end)}` +
  `&minmagnitude=${encodeURIComponent(minmag)}`;
delete msg.payload;
return msg;

// Input: USGS GeoJSON in msg.payload.
// Output: one INSERT per quake + one INSERT per paired control event.
// Control = same place as the quake, uniformly random time in the 2 years before it.
// This is the baseline: "what does the sky look like here when there is NO quake?"
const CONTROL_WINDOW_MS = 2 * 365.25 * 24 * 3600 * 1000;
const toSql = (ms) => new Date(ms).toISOString().replace('T', ' ').replace('Z', '');
// TABLE_PREFIX: set on the tab (double-click the tab), e.g. "anna_" -> table anna_events.
const T = env.get('TABLE_PREFIX') || '';
const SQL = `INSERT IGNORE INTO ${T}events ` +
  '(kind, source_id, paired_with, time_utc, latitude, longitude, depth_km, magnitude, place) ' +
  'VALUES (?,?,?,?,?,?,?,?,?)';

const out = [];
for (const f of (msg.payload && msg.payload.features) || []) {
  const p = f.properties;
  if (p.type !== 'earthquake' || p.mag == null) continue;
  const [lon, lat, depth] = f.geometry.coordinates;
  const controlTime = p.time - Math.random() * CONTROL_WINDOW_MS;

  out.push({ topic: SQL, payload: ['earthquake', f.id, null, toSql(p.time), lat, lon, depth, p.mag, p.place] });
  out.push({ topic: SQL, payload: ['control', 'ctrl-' + f.id, f.id, toSql(controlTime), lat, lon, depth, p.mag, null] });
}
node.status({ text: `${out.length / 2} quakes @ ${new Date().toISOString().slice(11, 16)}Z` });
return [out];

// Builds the query for events that still need their sky computed (sky_computed = 0).
// The table comes from the tab's environment variable TABLE_PREFIX (double-click the tab),
// e.g. "anna_" -> anna_events. So an imported flow works after setting the prefix there.
// time_iso: the time as an ISO string with milliseconds, in UTC (the database session runs in UTC).
const T = env.get('TABLE_PREFIX') || '';
msg.topic = 'SELECT id, latitude, longitude, ' +
  "CONCAT(DATE_FORMAT(time_utc, '%Y-%m-%dT%H:%i:%s.'), LPAD(FLOOR(MICROSECOND(time_utc) / 1000), 3, '0'), 'Z') AS time_iso " +
  `FROM ${T}events WHERE sky_computed = 0 ORDER BY id LIMIT 600`;
msg.payload = [];
return msg;

// Input: rows from "SELECT ... FROM <prefix>events WHERE sky_computed = 0".
// Output: one message per event (msg.event = the row).
const out = (msg.payload || []).map((row) => ({ event: row }));
node.status({ text: `${out.length} pending` });
return [out];

// Planetary position calculations, built on astronomy-engine.

const BODIES = [
  'Sun', 'Moon', 'Mercury', 'Venus', 'Mars',
  'Jupiter', 'Saturn', 'Uranus', 'Neptune', 'Pluto',
];

const ZODIAC = [
  'Aries', 'Taurus', 'Gemini', 'Cancer', 'Leo', 'Virgo',
  'Libra', 'Scorpio', 'Sagittarius', 'Capricorn', 'Aquarius', 'Pisces',
];

const ASPECTS = [
  { name: 'conjunction', angle: 0 },
  { name: 'sextile', angle: 60 },
  { name: 'square', angle: 90 },
  { name: 'trine', angle: 120 },
  { name: 'opposition', angle: 180 },
];

const round = (x, digits = 4) => Number(x.toFixed(digits));

/** Geocentric ecliptic longitude/latitude (true ecliptic of date), degrees. */
function eclipticOf(body, time) {
  const vec = Astronomy.GeoVector(body, time, true);
  return Astronomy.Ecliptic(vec);
}

/**
 * Heliocentric position (seen from the Sun, true ecliptic of date like eclipticOf), for drawing the
 * solar system from above. null for the Sun itself. The Earth is not in BODIES: seen from the Sun it
 * stands exactly opposite to where we see the Sun (longitude + 180°, same distance).
 */
function heliocentricOf(body, time) {
  if (body === 'Sun') return null;
  const vec = Astronomy.HelioVector(body, time);
  const ecl = Astronomy.Ecliptic(vec);
  return { longitudeDeg: round(ecl.elon, 5), latitudeDeg: round(ecl.elat, 5), distanceAU: round(vec.Length(), 8) };
}

function zodiacOf(elon) {
  const idx = Math.floor(elon / 30);
  return { sign: ZODIAC[idx], degreeInSign: round(elon - idx * 30, 4) };
}

/** True if the body's geocentric ecliptic longitude is decreasing. */
function isRetrograde(body, time) {
  if (body === 'Sun' || body === 'Moon') return false;
  const before = eclipticOf(body, time.AddDays(-0.5)).elon;
  const after = eclipticOf(body, time.AddDays(0.5)).elon;
  const delta = ((after - before + 540) % 360) - 180; // signed, handles 360° wrap
  return delta < 0;
}

function nextEvent(body, observer, direction, time) {
  const t = Astronomy.SearchRiseSet(body, observer, direction, time, 1);
  return t ? t.date.toISOString() : null; // null = no event within 24 h (polar day/night)
}

/**
 * Compute positions of the Sun, Moon and planets for a time and place.
 * @param {Date} date
 * @param {{latitude:number, longitude:number, elevation?:number}} place
 * @param {{orb?:number, riseSet?:boolean}} [options] orb = max deviation (degrees) for aspects,
 *   riseSet = also search next rise/set times (slowest part, default true)
 */
function computeSky(date, place, options = {}) {
  const orb = options.orb ?? 8;
  const riseSet = options.riseSet ?? true;
  const time = Astronomy.MakeTime(date);
  const observer = new Astronomy.Observer(place.latitude, place.longitude, place.elevation ?? 0);

  const bodies = BODIES.map((body) => {
    // Topocentric, equator of date: what the observer actually sees (includes parallax).
    const eqDate = Astronomy.Equator(body, time, observer, true, true);
    // J2000 coordinates, needed for IAU constellation lookup.
    const eqJ2000 = Astronomy.Equator(body, time, observer, false, true);
    const hor = Astronomy.Horizon(time, observer, eqDate.ra, eqDate.dec, 'normal');
    const ecl = eclipticOf(body, time);
    const constellation = Astronomy.Constellation(eqJ2000.ra, eqJ2000.dec);
    const illum = Astronomy.Illumination(body, time);

    return {
      body,
      equatorial: {
        rightAscensionHours: round(eqDate.ra, 6),
        declinationDeg: round(eqDate.dec, 5),
        distanceAU: round(eqDate.dist, 8),
        distanceKm: Math.round(eqDate.dist * Astronomy.KM_PER_AU),
      },
      horizontal: {
        azimuthDeg: round(hor.azimuth, 4), // 0 = north, 90 = east
        altitudeDeg: round(hor.altitude, 4), // includes atmospheric refraction
        aboveHorizon: hor.altitude > 0,
      },
      ecliptic: {
        longitudeDeg: round(ecl.elon, 5),
        latitudeDeg: round(ecl.elat, 5),
        ...zodiacOf(ecl.elon),
      },
      heliocentric: heliocentricOf(body, time),
      constellation: { symbol: constellation.symbol, name: constellation.name },
      magnitude: round(illum.mag, 2),
      phaseFraction: body === 'Sun' ? null : round(illum.phase_fraction, 4),
      retrograde: isRetrograde(body, time),
      nextRise: riseSet ? nextEvent(body, observer, +1, time) : null,
      nextSet: riseSet ? nextEvent(body, observer, -1, time) : null,
    };
  });

  return {
    time: time.date.toISOString(),
    observer: { latitude: place.latitude, longitude: place.longitude, elevation: place.elevation ?? 0 },
    moonPhaseDeg: round(Astronomy.MoonPhase(time), 3), // 0 new, 90 first quarter, 180 full, 270 last quarter
    bodies,
    aspects: computeAspects(bodies, orb),
  };
}

/** Angular relationships between every pair of bodies (by ecliptic longitude). */
function computeAspects(bodies, orb) {
  const result = [];
  for (let i = 0; i < bodies.length; i++) {
    for (let j = i + 1; j < bodies.length; j++) {
      const a = bodies[i];
      const b = bodies[j];
      let sep = Math.abs(a.ecliptic.longitudeDeg - b.ecliptic.longitudeDeg);
      if (sep > 180) sep = 360 - sep;
      for (const aspect of ASPECTS) {
        const deviation = Math.abs(sep - aspect.angle);
        if (deviation <= orb) {
          result.push({
            bodies: [a.body, b.body],
            aspect: aspect.name,
            separationDeg: round(sep, 3),
            orbDeg: round(deviation, 3),
          });
        }
      }
    }
  }
  return result.sort((x, y) => x.orbDeg - y.orbDeg);
}


// ---------------------------------------------------------------
// Input: msg.event = {id, latitude, longitude, time_iso}.
// Computes the sky with computeSky() (src/planets.js, inserted above this code when the
// flow is built; "Astronomy" comes from the astronomy-engine module in the Setup tab)
// and outputs SQL messages for body_positions, aspects and marking the event as done.
// REPLACE keeps it idempotent if an event is ever processed twice.
// TABLE_PREFIX: set on the tab (double-click the tab), e.g. "anna_" -> table anna_body_positions.
const T = env.get('TABLE_PREFIX') || '';
const ev = msg.event;
let sky;
try {
  sky = computeSky(new Date(ev.time_iso), { latitude: ev.latitude, longitude: ev.longitude }, { orb: 8, riseSet: false });
} catch (err) {
  node.warn(`Sky calculation failed for event ${ev.id}: ${err.message}`);
  return null; // event stays sky_computed = 0 and is retried on the next poll
}

function bulk(table, cols, rows) {
  const ph = '(' + cols.map(() => '?').join(',') + ')';
  return {
    topic: `REPLACE INTO ${table} (${cols.join(',')}) VALUES ${rows.map(() => ph).join(',')}`,
    payload: rows.flat(),
  };
}

const msgs = [bulk(T + 'body_positions', [
  'event_id', 'body', 'ra_hours', 'dec_deg', 'distance_au', 'azimuth_deg', 'altitude_deg',
  'above_horizon', 'ecl_lon_deg', 'ecl_lat_deg', 'zodiac_sign', 'degree_in_sign',
  'constellation', 'vis_magnitude', 'phase_fraction', 'retrograde', 'helio_lon_deg', 'helio_dist_au',
], sky.bodies.map((b) => [
  ev.id, b.body, b.equatorial.rightAscensionHours, b.equatorial.declinationDeg, b.equatorial.distanceAU,
  b.horizontal.azimuthDeg, b.horizontal.altitudeDeg, b.horizontal.aboveHorizon ? 1 : 0,
  b.ecliptic.longitudeDeg, b.ecliptic.latitudeDeg, b.ecliptic.sign, b.ecliptic.degreeInSign,
  b.constellation.name, b.magnitude, b.phaseFraction, b.retrograde ? 1 : 0,
  b.heliocentric ? b.heliocentric.longitudeDeg : null, b.heliocentric ? b.heliocentric.distanceAU : null,
]))];
if (sky.aspects.length) {
  msgs.push(bulk(T + 'aspects',
    ['event_id', 'body_a', 'body_b', 'aspect', 'separation_deg', 'orb_deg'],
    sky.aspects.map((a) => [ev.id, a.bodies[0], a.bodies[1], a.aspect, a.separationDeg, a.orbDeg])));
}
msgs.push({ topic: `UPDATE ${T}events SET moon_phase_deg = ?, sky_computed = 1 WHERE id = ?`, payload: [sky.moonPhaseDeg, ev.id] });
return [msgs];

// Input: PB2002 tectonic plates as GeoJSON in msg.payload (54 features, ~11 700 points).
// Output: per plate one upsert into `plates` (outline as MULTIPOLYGON) and the outline points
// in batches into `plate_points`. Upserts, so running it again changes nothing.
// Some plates come in several features (split at the date line): they are merged by code.
const PLATE_SQL = 'INSERT INTO plates (code, name, geom) VALUES (?, ?, ST_GeomFromText(?)) ' +
  'ON DUPLICATE KEY UPDATE name = VALUES(name), geom = VALUES(geom)';
const POINTS_PER_INSERT = 500;

const features = (msg.payload && msg.payload.features) || [];
if (!features.length) {
  node.error('Keine Platten in der Antwort (ist die URL erreichbar?)', msg);
  return null;
}

// code -> { name, polygons: [ [ring, ring, ...], ... ] }, ring = [[lon, lat], ...]
const plates = new Map();
for (const f of features) {
  const p = f.properties || {};
  const g = f.geometry || {};
  if (!p.Code || !g.coordinates) continue;
  const polygons = g.type === 'Polygon' ? [g.coordinates] : g.type === 'MultiPolygon' ? g.coordinates : [];
  if (!plates.has(p.Code)) plates.set(p.Code, { name: p.PlateName || p.Code, polygons: [] });
  plates.get(p.Code).polygons.push(...polygons);
}

const wktRing = (ring) => '(' + ring.map(([lon, lat]) => `${lon} ${lat}`).join(',') + ')';
const out = [];
let pointCount = 0;
for (const [code, { name, polygons }] of plates) {
  const wkt = 'MULTIPOLYGON(' + polygons.map((poly) => '(' + poly.map(wktRing).join(',') + ')').join(',') + ')';
  out.push({ topic: PLATE_SQL, payload: [code, name, wkt] });

  const rows = [];
  polygons.flat().forEach((ring, part) => ring.forEach(([lon, lat], seq) => rows.push([code, part, seq, lat, lon])));
  for (let i = 0; i < rows.length; i += POINTS_PER_INSERT) {
    const batch = rows.slice(i, i + POINTS_PER_INSERT);
    out.push({
      topic: 'INSERT INTO plate_points (code, part, seq, latitude, longitude) VALUES ' +
        batch.map(() => '(?,?,?,?,?)').join(',') +
        ' ON DUPLICATE KEY UPDATE latitude = VALUES(latitude), longitude = VALUES(longitude)',
      payload: batch.flat(),
    });
  }
  pointCount += rows.length;
}
node.status({ text: `${plates.size} Platten, ${pointCount} Punkte @ ${new Date().toISOString().slice(11, 16)}Z` });
return [out];
